package com.crm.crm.controller;
import com.crm.crm.entity.*; import com.crm.crm.service.LeadService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/leads") public class LeadController {private final LeadService s; public LeadController(LeadService s){this.s=s;} private void opts(Model m){m.addAttribute("statuses",LeadStatus.values());m.addAttribute("sources",LeadSource.values());} @GetMapping public String list(Model m){m.addAttribute("leads",s.findAll());return "leads/list";} @GetMapping("/new") public String form(Model m){m.addAttribute("lead",new Lead());opts(m);return "leads/form";} @GetMapping("/edit/{id}") public String edit(@PathVariable Long id,Model m){return s.findById(id).map(l->{m.addAttribute("lead",l);opts(m);return "leads/form";}).orElse("redirect:/leads");} @PostMapping("/save") public String save(@Valid @ModelAttribute Lead lead,BindingResult br,Model m){if(br.hasErrors()){opts(m);return "leads/form";}s.save(lead);return "redirect:/leads";} @PostMapping("/delete/{id}") public String delete(@PathVariable Long id){s.delete(id);return "redirect:/leads";}}
